using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Media3D;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public sealed class Viewport3DControl:Grid { readonly Viewport3D view=new();readonly Model3DGroup scene=new();readonly PerspectiveCamera camera=new(){FieldOfView=55,Position=new Point3D(10,-12,9),LookDirection=new Vector3D(-10,12,-7),UpDirection=new Vector3D(0,0,1)};readonly Dictionary<Model3D,Guid> objectModels=new();ShellProject? project;Guid? selected;Point? orbitStart;Point? dragStart;Vec3? dragObjectStart;GizmoAxis activeAxis=GizmoAxis.None;double yaw=.7,pitch=.55,distance=18;public event Action<Guid>? ObjectSelected;public event Action? ObjectMoved;public Viewport3DControl(){Background=new SolidColorBrush(Color.FromRgb(12,12,16));view.Camera=camera;view.Children.Add(new ModelVisual3D{Content=scene});Children.Add(view);MouseWheel+=Wheel;MouseRightButtonDown+=OrbitDown;MouseRightButtonUp+=OrbitUp;MouseLeftButtonDown+=LeftDown;MouseLeftButtonUp+=LeftUp;MouseMove+=Move;Loaded+=(_,_)=>RenderScene();}public void SetProject(ShellProject p,Guid? selectedId=null){project=p;selected=selectedId;RenderScene();}public void SetSelected(Guid? id){selected=id;RenderScene();}public void RenderScene(){scene.Children.Clear();objectModels.Clear();scene.Children.Add(new AmbientLight(Color.FromRgb(105,105,120)));scene.Children.Add(new DirectionalLight(Colors.White,new Vector3D(-.4,.6,-1)));DrawGrid();if(project==null)return;foreach(var o in project.Objects){var m=Box(o,o.Id==selected);objectModels[m]=o.Id;scene.Children.Add(m);}if(selected is Guid id){var o=project.Objects.FirstOrDefault(x=>x.Id==id);if(o!=null)DrawMoveGizmo(o);}}GeometryModel3D Box(SceneObject o,bool active){var sx=Math.Max(.02,o.Scale.X)/2;var sy=Math.Max(.02,o.Scale.Y)/2;var sz=Math.Max(.02,o.Scale.Z)/2;var pts=new Point3DCollection{new(-sx,-sy,-sz),new(sx,-sy,-sz),new(sx,sy,-sz),new(-sx,sy,-sz),new(-sx,-sy,sz),new(sx,-sy,sz),new(sx,sy,sz),new(-sx,sy,sz)};var idx=new Int32Collection{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7};var mesh=new MeshGeometry3D{Positions=pts,TriangleIndices=idx};var color=active?Color.FromRgb(176,132,245):o.Type==SceneObjectType.Prop?Color.FromRgb(125,90,190):Color.FromRgb(105,76,165);var mat=new DiffuseMaterial(new SolidColorBrush(color));var model=new GeometryModel3D(mesh,mat){BackMaterial=mat};var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),o.Rotation.X)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,1,0),o.Rotation.Y)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),o.Rotation.Z)));t.Children.Add(new TranslateTransform3D(o.Position.X,o.Position.Y,o.Position.Z));model.Transform=t;return model;}void DrawMoveGizmo(SceneObject o){var p=new Point3D(o.Position.X,o.Position.Y,o.Position.Z);scene.Children.Add(Axis(p,new Vector3D(2.2,0,0),Colors.Red,GizmoAxis.X));scene.Children.Add(Axis(p,new Vector3D(0,2.2,0),Colors.LimeGreen,GizmoAxis.Y));scene.Children.Add(Axis(p,new Vector3D(0,0,2.2),Colors.DodgerBlue,GizmoAxis.Z));}GeometryModel3D Axis(Point3D p,Vector3D d,Color c,GizmoAxis axis){var m=Line(p,p+d,.055,c);m.SetValue(FrameworkElement.TagProperty,axis);return m;}void DrawGrid(){for(int i=-20;i<=20;i++){scene.Children.Add(Line(new Point3D(i,-20,0),new Point3D(i,20,0),.01,Color.FromRgb(42,42,52)));scene.Children.Add(Line(new Point3D(-20,i,0),new Point3D(20,i,0),.01,Color.FromRgb(42,42,52)));}}GeometryModel3D Line(Point3D a,Point3D b,double width,Color color){var d=b-a;var len=d.Length;var mesh=new MeshGeometry3D{Positions=new Point3DCollection{new(-width,-len/2,0),new(width,-len/2,0),new(width,len/2,0),new(-width,len/2,0)},TriangleIndices=new Int32Collection{0,1,2,0,2,3}};var m=new GeometryModel3D(mesh,new DiffuseMaterial(new SolidColorBrush(color)));var angle=Math.Atan2(d.Y,d.X)*180/Math.PI-90;var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),angle)));if(Math.Abs(d.Z)>Math.Abs(d.X)+Math.Abs(d.Y))t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),90)));t.Children.Add(new TranslateTransform3D((a.X+b.X)/2,(a.Y+b.Y)/2,(a.Z+b.Z)/2));m.Transform=t;return m;}void OrbitDown(object s,MouseButtonEventArgs e){orbitStart=e.GetPosition(this);CaptureMouse();}void OrbitUp(object s,MouseButtonEventArgs e){orbitStart=null;ReleaseMouseCapture();}void LeftDown(object s,MouseButtonEventArgs e){var p=e.GetPosition(view);var hit=VisualTreeHelper.HitTest(view,p) as RayMeshGeometry3DHitTestResult;if(hit?.ModelHit is Model3D model){if(model.GetValue(FrameworkElement.TagProperty) is GizmoAxis axis&&axis!=GizmoAxis.None&&selected!=null){activeAxis=axis;dragStart=e.GetPosition(this);var o=project?.Objects.FirstOrDefault(x=>x.Id==selected);if(o!=null)dragObjectStart=o.Position;CaptureMouse();e.Handled=true;return;}if(objectModels.TryGetValue(model,out var id)){selected=id;ObjectSelected?.Invoke(id);RenderScene();e.Handled=true;}}}void LeftUp(object s,MouseButtonEventArgs e){activeAxis=GizmoAxis.None;dragStart=null;dragObjectStart=null;if(IsMouseCaptured)ReleaseMouseCapture();}void Move(object s,MouseEventArgs e){if(orbitStart!=null&&e.RightButton==MouseButtonState.Pressed){var p=e.GetPosition(this);yaw+=(p.X-orbitStart.Value.X)*.01;pitch=Math.Clamp(pitch+(p.Y-orbitStart.Value.Y)*.01,-1.35,1.35);orbitStart=p;UpdateCamera();return;}if(activeAxis==GizmoAxis.None||dragStart==null||dragObjectStart==null||selected==null||project==null||e.LeftButton!=MouseButtonState.Pressed)return;var now=e.GetPosition(this);var delta=(float)((now.X-dragStart.Value.X-(now.Y-dragStart.Value.Y))*.015);var o=project.Objects.FirstOrDefault(x=>x.Id==selected);if(o==null)return;var p=dragObjectStart;var next=activeAxis switch{GizmoAxis.X=>new Vec3(p.X+delta,p.Y,p.Z),GizmoAxis.Y=>new Vec3(p.X,p.Y+delta,p.Z),GizmoAxis.Z=>new Vec3(p.X,p.Y,p.Z+delta),_=>p};var g=project.Settings.GridSize;if(g>0)next=new Vec3(Snap(next.X,g),Snap(next.Y,g),Snap(next.Z,g));o.Position=next;RenderScene();ObjectMoved?.Invoke();}void Wheel(object s,MouseWheelEventArgs e){distance=Math.Clamp(distance-e.Delta/120.0,3,80);UpdateCamera();}void UpdateCamera(){var cp=Math.Cos(pitch);var pos=new Point3D(Math.Cos(yaw)*cp*distance,Math.Sin(yaw)*cp*distance,Math.Sin(pitch)*distance+3);camera.Position=pos;camera.LookDirection=new Vector3D(-pos.X,-pos.Y,1.5-pos.Z);}static float Snap(float v,float g)=>MathF.Round(v/g)*g;enum GizmoAxis{None,X,Y,Z}}
